import boto3

def translate_dictionary_values(dictionary: dict, source_language: str, target_language: str) -> dict:
    """
    Translates dictionary values while preserving keys using AWS Translate.
    """
    client = boto3.client("translate")
    translated_dictionary = {}
    for key, value in dictionary.items():
        if isinstance(value, str):
            response = client.translate_text(
                Text=value,
                SourceLanguageCode=source_language,
                TargetLanguageCode=target_language
            )
            translated_dictionary[key] = response["TranslatedText"]
        else:
            translated_dictionary[key] = value
    return translated_dictionary

from dataclasses import dataclass

@dataclass
class TranslationRequest:
    text: str
    source_language: str
    target_language: str

@dataclass
class TranslationResponse:
    translated_text: str
    source_language: str
    target_language: str

def normalize_text_input(text_input: str) -> str:
    """
    Normalizes text input for translation.
    """
    return text_input.strip()

def parse_translation_response(response: dict) -> TranslationResponse:
    """
    Parses the AWS Translate response into a TranslationResponse object.
    """
    return TranslationResponse(
        translated_text=response["TranslatedText"],
        source_language=response["SourceLanguageCode"],
        target_language=response["TargetLanguageCode"]
    )

import boto3

def unsafe_copy_check(text: str, language_code: str) -> list[dict]:
    """
    Checks localized copy for unsafe content using AWS Comprehend Moderation.
    """
    comprehend = boto3.client("comprehend")

    try:
        response = comprehend.detect_toxic_content(
            TextContent={'Text': text},
            LanguageCode=language_code
        )
        return response.get('Result', {}).get('Labels', [])
    except comprehend.exceptions.UnsupportedLanguageException:
        return [{'Message': f'Language {language_code} is not supported for toxic content detection.'}]
    except Exception as e:
        return [{'Error': str(e)}]
